import Foundation

/// Localized text for the owner-approved wallpaper install, respring and owned-management flow.
enum MirsaWallpaperActionStrings {
    enum Key: CaseIterable {
        case installTitle, installBody, installConfirm, cancel
        case respringTitle, respringBody, respringConfirm, respringLater
        case ownedTitle, ownedFooter, ownedEmpty, refresh, inspect, unknownWarning, diagnosticDone
        case deleteItem, deleteTitle, deleteBody, deleteConfirm
        case cleanup, cleanupTitle, cleanupBody, cleanupConfirm
        case deleteDone, cleanupDone, failedPrefix, busy, importRemoveHint
        case journalTitle, journalFooter, journalEmpty, reconcile, reconcileTitle, reconcileBody, reconcileConfirm, reconcileClearedDone, reconcilePresentTitle, reconcilePresentBody, keepIt, journalPending, journalCopied, errJournalExists, errTimeBudget, errIncomplete, errBusy
    }
    static func text(_ key: Key, language: AppLanguage = AppLanguageStore.snapshot) -> String {
        let column: Int
        switch language {
        case .english: column = 0
        case .arabic: column = 1
        case .german: column = 2
        case .kurmanji: column = 3
        case .sorani: column = 4
        }
        return values[key]![column]
    }
    /// Localized "Wallpaper N" with locale-formatted index (AR/CKB Arabic-Indic digits).
    static func fallbackName(_ index: Int, language: AppLanguage = AppLanguageStore.snapshot) -> String {
        let f = NumberFormatter()
        let word: String
        switch language {
        case .english: f.locale = Locale(identifier: "en"); word = "Wallpaper"
        case .arabic: f.locale = Locale(identifier: "ar"); word = "خلفية"
        case .german: f.locale = Locale(identifier: "de"); word = "Hintergrund"
        case .kurmanji: f.locale = Locale(identifier: "ku"); word = "Wênesazî"
        case .sorani: f.locale = Locale(identifier: "ckb"); word = "وێنەزەمینە"
        }
        return word + " " + (f.string(from: NSNumber(value: index)) ?? String(index))
    }
    static let values: [Key: [String]] = [
        .installTitle: ["Install selected wallpapers?", "تثبّت الخلفيات المحددة؟", "Ausgewählte Hintergründe installieren?", "Wênesaziyên hilbijartî saz bikim?", "ئەو وێنەزەمینانە دابمەزرێنم کە هەڵبژێردراون؟"],
        .installBody: ["This copies the selected wallpapers into the iOS wallpaper gallery. Your imported files stay as they are. You will be asked separately before anything restarts.", "رح ينسخ الخلفيات المحددة لمعرض خلفيات iOS. ملفاتك المستوردة بتضل متل ما هي. رح نسألك لحالها قبل ما يعيد التشغيل أي شي.", "Die ausgewählten Hintergründe werden in die iOS-Hintergrundgalerie kopiert. Deine importierten Dateien bleiben unverändert. Vor einem Neustart wirst du separat gefragt.", "Ev wênesaziyên hilbijartî ji galeriya wênesaziyên iOS re kopî dike. Pelên te yên hatine import kirin wekî xwe dimînin. Berî ku tiştek ji nû ve dest pê bike, dê ji te ji aliyekî din ve bê pirsîn.", "ئەمە وێنەزەمینە هەڵبژێردراوەکان کۆپی دەکات بۆ گالەری وێنەزەمینەی iOS. فایلە هاوردەکراوەکانت وەک خۆیان دەمێننەوە. پێش هەر دووبارە دەستپێکردنەوەیەک جیا پرسیارت لێ دەکرێت."],
        .installConfirm: ["Install", "تثبيت", "Installieren", "Saz bike", "دامەزراندن"],
        .cancel: ["Cancel", "إلغاء", "Abbrechen", "Betal bike", "پاشگەزبوونەوە"],
        .respringTitle: ["Restart the screen now?", "تعيد تشغيل الشاشة هلق؟", "Bildschirm jetzt neu starten?", "Ekranê niha ji nû ve dest pê bikim?", "ئێستا شاشەکە دووبارە دەست پێ بکەمەوە؟"],
        .respringBody: ["iOS needs a screen restart to show the change in the wallpaper gallery. The screen may flicker, apps or the screen may restart, and unsaved work can be lost. Success is only confirmed when you check the wallpaper gallery yourself.", "لازم iOS يعيد تشغيل الشاشة ليظهر التغيير بمعرض الخلفيات. الشاشة ممكن ترمش، والتطبيقات أو الشاشة ممكن ترجع تشتغل من جديد، وأي شي مو محفوظ ممكن يضيع. ما منعتبره نجح إلا لما تتأكد بنفسك من معرض الخلفيات.", "iOS braucht einen Neustart des Bildschirms, damit die Änderung in der Galerie erscheint. Der Bildschirm kann flackern, Apps oder der Bildschirm können neu starten, nicht gespeicherte Arbeit kann verloren gehen. Erfolg gilt erst, wenn du die Galerie selbst geprüft hast.", "iOS ji bo nîşandana guhertinê di galeriyê de pêdivî bi vemirandin û vekirina ekranê heye. Dibe ku ekran biriqe, sepan an ekran ji nû ve dest pê bikin û xebata tomarnekirî winda bibe. Serkeftin tenê piştî ku tu bi xwe galeriyê kontrol bikî tê pejirandin.", "iOS پێویستی بە دووبارە دەستپێکردنەوەی شاشە هەیە بۆ پیشاندانی گۆڕانکاری لە گالەری. ڕەنگە شاشە بتروسکێتەوە، ئەپەکان یان شاشە دووبارە دەست پێ بکەنەوە و ئەو کارەی پاشەکەوت نەکراوە لەدەست بچێت. سەرکەوتن تەنها دوای ئەوە دەسەلمێندرێت کە خۆت گالەری بپشکنیت."],
        .respringConfirm: ["Restart screen", "إعادة تشغيل الشاشة", "Bildschirm neu starten", "Ekranê ji nû ve dest pê bike", "دووبارە دەستپێکردنەوەی شاشە"],
        .respringLater: ["Not now", "مو هلق", "Nicht jetzt", "Ne niha", "نەک ئێستا"],
        .ownedTitle: ["Wallpaper diagnostics", "فحص الخلفيات", "Hintergrund-Diagnose", "Kontrola wênesaziyan", "پشکنینی وێنەزەمینەکان"],
        .ownedFooter: ["This is a partial diagnostic build, not all-custom deletion. Unclassified entries may be Apple wallpapers and are inspect-only. Mirsa journal rows keep their existing strict delete checks. Refresh records bounded metadata; Inspect compares a Mirsa journal's original paths and hashes. Copy the Flash Log to share evidence. No wallpaper is changed by inspection.", "هاي نسخة فحص جزئية، مو حذف كل الخلفيات المخصصة. العناصر يلي ما تأكدنا منها ممكن تكون من Apple، وفيك تفحصها بس. خلفيات سجل مرسى بيضل إلها نفس فحص الحذف الصارم. التحديث بيسجل معلومات محدودة، والفحص بيقارن المسارات والبصمات بسجل مرسى الأصلي. انسخ سجل الفلاش لتشارك النتيجة. الفحص ما بيغيّر أي خلفية.", "Dies ist ein teilweiser Diagnose-Build, kein Löschen aller eigenen Hintergründe. Unklassifizierte Einträge können von Apple sein und sind nur prüfbar. Für Mirsa-Einträge bleiben die strengen Löschprüfungen bestehen. Aktualisieren erfasst begrenzte Metadaten; Prüfen vergleicht Originalpfade und Hashes des Mirsa-Eintrags. Teile das Flash-Protokoll als Nachweis. Prüfen verändert keine Hintergründe.", "Ev guhertoyeke kontrolê ya beşî ye, ne jêbirina hemû wênesaziyên taybet e. Hêmanên nehatine nasîn dibe ku yên Apple bin û tenê tên kontrolkirin. Kontrolên hişk ên jêbirinê ji bo tomarên Mirsa dimînin. Nûvekirin agahiyên sînorkirî tomar dike; Kontrol rê û hashên orîjînal ên tomara Mirsa dide ber hev. Ji bo parvekirina encamê qeyda Flash kopî bike. Kontrol wênesaziyê naguherîne.", "ئەمە وەشانێکی پشکنینی بەشییە، نەک سڕینەوەی هەموو وێنەزەمینە تایبەتەکان. بەشە نەناسراوەکان ڕەنگە هی Apple بن و تەنها دەتوانرێت بپشکنرێن. پشکنینە توندەکانی سڕینەوە بۆ تۆمارەکانی مرسی دەمێننەوە. نوێکردنەوە زانیاری سنووردار تۆمار دەکات؛ پشکنین ڕێڕەو و هاشە ڕەسەنەکانی تۆماری مرسی بەراورد دەکات. بۆ ناردنی ئەنجام تۆماری Flash کۆپی بکە. پشکنین هیچ وێنەزەمینەیەک ناگۆڕێت."],
        .ownedEmpty: ["No wallpaper entries loaded.", "ما تحمّلت عناصر خلفيات.", "Keine Hintergrundeinträge geladen.", "Tu tomarên wênesaziyê nehatine barkirin.", "هیچ تۆمارێکی وێنەزەمینە بار نەکراوە."],
        .unknownWarning: ["Unclassified, may be Apple. Inspect only; deletion locked.", "مو معروف مصدرها، ممكن تكون من Apple. فحص بس، الحذف مقفول.", "Nicht klassifiziert, eventuell Apple. Nur prüfen, Löschen gesperrt.", "Nehatiye nasîn, dibe ku ya Apple be. Tenê kontrol, jêbirin girtî ye.", "نەناسراوە، ڕەنگە هی Apple بێت. تەنها پشکنین، سڕینەوە داخراوە."],
        .inspect: ["Inspect (read-only)", "فحص بدون تغيير", "Prüfen (nur lesen)", "Kontrol (tenê xwendin)", "پشکنین (تەنها خوێندنەوە)"],
        .diagnosticDone: ["Inspection finished. Copy the Flash Log. Partial or unreadable results are not proof of absence or custom origin.", "خلص الفحص. انسخ سجل الفلاش. النتيجة الناقصة أو يلي ما انقرت مو دليل إن الخلفية محذوفة أو مخصصة.", "Prüfung beendet. Kopiere das Flash-Protokoll. Unvollständige oder unlesbare Ergebnisse beweisen weder Abwesenheit noch eigene Herkunft.", "Kontrol qediya. Qeyda Flash kopî bike. Encamên beşî an nexwendbar delîla nebûnê an çavkaniya taybet nînin.", "پشکنین تەواو بوو. تۆماری Flash کۆپی بکە. ئەنجامی ناتەواو یان نەخوێنراو بەڵگەی نەبوون یان سەرچاوەی تایبەت نییە."],
        .refresh: ["Refresh list", "تحديث القائمة", "Liste aktualisieren", "Lîsteyê nû bike", "نوێکردنەوەی لیست"],
        .deleteItem: ["Delete from gallery", "حذف من المعرض", "Aus Galerie löschen", "Ji galeriyê jê bibe", "سڕینەوە لە گالەری"],
        .deleteTitle: ["Delete this wallpaper?", "تحذف هالخلفية؟", "Diesen Hintergrund löschen?", "Ev wênesazî jê bibim?", "ئەم وێنەزەمینەیە بسڕمەوە؟"],
        .deleteBody: ["This removes only the selected custom wallpaper from the system gallery. It may have been installed by another app. Your imported .tendies file stays, and other items are not touched. If it is your active lock screen, what happens is unknown. You will be asked separately about restarting the screen.", "هيك بيحذف بس الخلفية المخصصة يلي اخترتها من معرض النظام. ممكن تكون مثبّتة من تطبيق تاني. ملف .tendies المستورد بيضل وباقي العناصر ما بتنلمس. إذا كانت شاشة القفل الحالية، ما منعرف شو رح يصير. رح نسألك لحالها عن إعادة تشغيل الشاشة.", "Dadurch wird nur der ausgewählte eigene Hintergrund aus der System-Galerie entfernt. Er kann von einer anderen App installiert worden sein. Deine importierte .tendies-Datei bleibt erhalten, andere Elemente bleiben unberührt. Ist er dein aktiver Sperrbildschirm, ist das Ergebnis unbekannt. Zum Neustart des Bildschirms wirst du separat gefragt.", "Ev tenê wênesaziya taybet a hilbijartî ji galeriya pergalê radike. Dibe ku ji hêla sepanek din ve hatibe saz kirin. Pela te ya .tendies dimîne û hêmanên din nayên destlêdan. Heke ev kilîta te ya çalak be, encam nayê zanîn. Dê derbarê vemirandina ekranê de ji te ji aliyekî din bê pirsîn.", "ئەمە تەنها ئەو وێنەزەمینە تایبەتەی هەڵتبژاردووە لە گالەری سیستەم دەسڕێتەوە. لەوانەیە ئەپێکی تر دایمەزراندبێت. فایلی .tendies هاوردەکراوەکەت دەمێنێتەوە و بەشەکانی تر دەست لێ نادرێن. ئەگەر شاشەی قفڵی چالاکت بێت، ئەنجامەکەی نەزانراوە. جیا پرسیارت لێ دەکرێت دەربارەی دووبارە دەستپێکردنەوەی شاشە."],
        .deleteConfirm: ["Delete", "حذف", "Löschen", "Jê bibe", "سڕینەوە"],
        .cleanup: ["Clean up Mirsa leftovers", "تنظيف مخلفات مرسى", "Mirsa-Reste aufräumen", "Bermahiyên Mirsa paqij bike", "پاککردنەوەی پاشماوەکانی مرسی"],
        .cleanupTitle: ["Clean up leftovers?", "تنظّف المخلفات؟", "Reste aufräumen?", "Bermahiyan paqij bikim?", "پاشماوەکان پاک بکەمەوە؟"],
        .cleanupBody: ["This removes only Mirsa's own temporary extraction files and records of wallpapers that are verified to be gone already. No wallpaper is deleted from the system gallery and no restart is needed.", "هيك بيشيل بس الملفات المؤقتة يلي مرسى فكّها بنفسه وسجلات خلفيات تأكدنا إنها انحذفت أصلاً. ما بيحذف أي خلفية من معرض النظام وما بدك إعادة تشغيل.", "Entfernt nur Mirsas eigene temporäre Entpackdateien und Einträge zu Hintergründen, die nachweislich schon weg sind. Es wird keine Hintergrundgalerie-Datei gelöscht und kein Neustart ist nötig.", "Ev tenê pelên demkî yên Mirsa bi xwe û tomarên wênesaziyên ku piştrast bûye jixwe nemane radike. Tu wênesazî ji galeriya pergalê nayê jêbirin û ji nû ve destpêkirin ne pêwîst e.", "ئەمە تەنها فایلە کاتییەکانی مرسی خۆی و تۆمارەکانی ئەو وێنەزەمینانە دەسڕێتەوە کە دڵنیابووین پێشتر نەماون. هیچ وێنەزەمینەیەک لە گالەری سیستەم ناسڕدرێتەوە و پێویست بە دووبارە دەستپێکردنەوە ناکات."],
        .cleanupConfirm: ["Clean up", "نظّف", "Aufräumen", "Paqij bike", "پاک بکەرەوە"],
        .deleteDone: ["Deleted from the gallery. Check the wallpaper gallery yourself.", "انحذفت من المعرض. تأكد بنفسك من معرض الخلفيات.", "Aus der Galerie gelöscht. Prüfe die Hintergrundgalerie selbst.", "Ji galeriyê hate jêbirin. Galeriyê bi xwe kontrol bike.", "لە گالەری سڕایەوە. خۆت گالەری بپشکنە."],
        .cleanupDone: ["Cleanup finished.", "خلص التنظيف.", "Aufräumen abgeschlossen.", "Paqijkirin qediya.", "پاککردنەوە تەواو بوو."],
        .failedPrefix: ["Failed: ", "فشل: ", "Fehlgeschlagen: ", "Têk çû: ", "شکستی هێنا: "],
        .busy: ["Please wait, another wallpaper job is running.", "استنى، في شغلة خلفيات تانية شغالة.", "Bitte warten, ein anderer Hintergrund-Vorgang läuft.", "Ji kerema xwe bisekine, karekî din yê wênesaziyê dixebite.", "تکایە چاوەڕێ بە، کارێکی تری وێنەزەمینە کار دەکات."],
        .importRemoveHint: ["The trash icon in the list above only removes the imported file.", "أيقونة الحذف بالقائمة فوق بتشيل الملف المستورد بس.", "Das Papierkorb-Symbol oben entfernt nur die importierte Datei.", "Îkona çopê di lîsteya jorîn de tenê pela import kirî radike.", "ئایکۆنی تەنەکەی خۆڵ لە لیستی سەرەوە تەنها فایلە هاوردەکراوەکە لادەبات."],
        .journalTitle: ["Old install records", "سجلات التثبيت القديمة", "Alte Installationseinträge", "Tomarên sazkirinê yên kevn", "تۆمارە کۆنەکانی دامەزراندن"],
        .journalFooter: ["These are records of earlier Mirsa installs. They show even if the gallery list fails. Reconcile checks the exact wallpaper first, nothing is changed without your confirmation.", "هدول سجلات تثبيتات مرسى القديمة. بتظهر حتى لو قائمة المعرض فشلت. المطابقة بتفحص الخلفية بالضبط أول، وما بيتغير شي بدون تأكيدك.", "Das sind Einträge früherer Mirsa-Installationen. Sie erscheinen auch, wenn die Galerieliste fehlschlägt. Der Abgleich prüft zuerst genau diesen Hintergrund, ohne deine Bestätigung ändert sich nichts.", "Ev tomarên sazkirinên Mirsa yên berê ne. Heta ku lîsteya galeriyê têk biçe jî tên nîşandan. Lihevhatin pêşî wênesaziya rast kontrol dike, bê erêkirina te tiştek nayê guhertin.", "ئەمانە تۆماری دامەزراندنە کۆنەکانی مرسین. تەنانەت ئەگەر لیستی گالەری شکست بهێنێت پیشان دەدرێن. ڕێکخستنەوە سەرەتا ئەو وێنەزەمینەیە بە دروستی دەپشکنێت و بەبێ پشتڕاستکردنەوەی تۆ هیچ ناگۆڕدرێت."],
        .journalEmpty: ["No old install records.", "ما في سجلات تثبيت قديمة.", "Keine alten Installationseinträge.", "Tomarên sazkirinê yên kevn tune ne.", "هیچ تۆمارێکی دامەزراندنی کۆن نییە."],
        .reconcile: ["Reconcile / clear record", "مطابقة / مسح السجل", "Abgleichen / Eintrag löschen", "Lihevhatin / tomarê paqij bike", "ڕێکخستنەوە / سڕینەوەی تۆمار"],
        .reconcileTitle: ["Check this old install record?", "تفحص سجل التثبيت القديم؟", "Alten Installationseintrag prüfen?", "Tomara sazkirinê ya kevn kontrol bikim?", "تۆماری دامەزراندنی کۆن بپشکنم؟"],
        .reconcileBody: ["Mirsa first checks whether this exact wallpaper still exists. If it is gone, only the old record is cleared. If it still exists, nothing is removed here and you are offered a separate safe delete.", "مرسى رح يفحص أول إذا هالخلفية بالضبط لساتها موجودة. إذا انحذفت، بيتمسح السجل القديم بس. إذا لساتها موجودة، ما بيتشال شي هون ورح نعرضلك حذف آمن لحاله.", "Mirsa prüft zuerst, ob genau dieser Hintergrund noch existiert. Ist er weg, wird nur der alte Eintrag gelöscht. Existiert er noch, wird hier nichts entfernt und dir wird ein separates sicheres Löschen angeboten.", "Mirsa pêşî kontrol dike ka ev wênesazî hê heye. Heke çûbe, tenê tomara kevn tê paqijkirin. Heke hê hebe, li vir tiştek nayê jêbirin û jêbirinek ewle ya cuda tê pêşkêşkirin.", "مرسی سەرەتا دەپشکنێت ئایا ئەم وێنەزەمینەیە هێشتا هەیە. ئەگەر نەمابێت تەنها تۆمارە کۆنەکە پاک دەکرێتەوە. ئەگەر هێشتا هەبێت لێرە هیچ ناسڕدرێتەوە و سڕینەوەیەکی سەلامەتی جیا پێشنیار دەکرێت."],
        .reconcileConfirm: ["Check", "فحص", "Prüfen", "Kontrol bike", "بپشکنە"],
        .reconcileClearedDone: ["Old record cleared. The wallpaper was already gone.", "انمسح السجل القديم. الخلفية كانت محذوفة أصلاً.", "Alter Eintrag gelöscht. Der Hintergrund war schon weg.", "Tomara kevn hate paqijkirin. Wênesazî jixwe nemabû.", "تۆمارە کۆنەکە پاک کرایەوە. وێنەزەمینەکە پێشتر نەمابوو."],
        .reconcilePresentTitle: ["This wallpaper still exists", "هالخلفية لساتها موجودة", "Dieser Hintergrund existiert noch", "Ev wênesazî hê heye", "ئەم وێنەزەمینەیە هێشتا هەیە"],
        .reconcilePresentBody: ["Nothing was changed. You can delete this exact Mirsa-installed wallpaper from the gallery now. Your imported .tendies file stays. Or keep it and leave the record as is.", "ما تغير شي. فيك تحذف هالخلفية بالضبط يلي ثبتها مرسى من المعرض هلق. ملف .tendies المستورد بيضل. أو خليها وخلي السجل متل ما هو.", "Es wurde nichts geändert. Du kannst genau diesen von Mirsa installierten Hintergrund jetzt aus der Galerie löschen. Deine importierte .tendies-Datei bleibt. Oder behalte ihn und lass den Eintrag unverändert.", "Tiştek nehat guhertin. Tu dikarî niha vê wênesaziya rast a ji hêla Mirsa ve hatî sazkirin ji galeriyê jê bibî. Pela .tendies dimîne. An jî wê bihêle û tomarê wekî xwe bihêle.", "هیچ نەگۆڕدرا. دەتوانیت ئێستا ئەم وێنەزەمینەیە کە مرسی دایمەزراندووە لە گالەری بسڕیتەوە. فایلی .tendies دەمێنێتەوە. یان بیهێڵەرەوە و تۆمارەکە وەک خۆی بهێڵەوە."],
        .keepIt: ["Keep", "خليها", "Behalten", "Bihêle", "بیهێڵەرەوە"],
        .journalPending: ["Install not completed", "التثبيت ما خلص", "Installation unvollständig", "Sazkirin neqediya", "دامەزراندن تەواو نەبوو"],
        .journalCopied: ["Installed", "مثبّتة", "Installiert", "Hate sazkirin", "دامەزرا"],
        .errJournalExists: ["This wallpaper already has an old Mirsa install record. Open “Old install records” below and reconcile or clear it first.", "هالخلفية إلها سجل تثبيت قديم من مرسى. افتح «سجلات التثبيت القديمة» تحت وطابقه أو امسحه أول.", "Für diesen Hintergrund gibt es schon einen alten Mirsa-Installationseintrag. Öffne unten „Alte Installationseinträge“ und gleiche ihn ab oder lösche ihn zuerst.", "Ji bo vê wênesaziyê tomarek sazkirinê ya kevn a Mirsa heye. Li jêr «Tomarên sazkirinê yên kevn» veke û pêşî lihev bîne an paqij bike.", "ئەم وێنەزەمینەیە تۆمارێکی دامەزراندنی کۆنی مرسی هەیە. «تۆمارە کۆنەکانی دامەزراندن» لە خوارەوە بکەرەوە و سەرەتا ڕێکی بخە یان بیسڕەوە."],
        .errTimeBudget: ["Listing the gallery took too long. Your old install records below still work. Try Refresh again.", "قراءة المعرض أخدت وقت كتير. سجلات التثبيت القديمة تحت لساتها شغالة. جرّب تحديث كمان مرة.", "Das Auslesen der Galerie hat zu lange gedauert. Die alten Installationseinträge unten funktionieren weiterhin. Versuche erneut zu aktualisieren.", "Xwendina galeriyê pir dirêj kişand. Tomarên sazkirinê yên kevn li jêr hê dixebitin. Dîsa nûve bike.", "خوێندنەوەی گالەری زۆر خایاند. تۆمارە کۆنەکانی دامەزراندن لە خوارەوە هێشتا کار دەکەن. دووبارە نوێ بکەرەوە."],
        .errIncomplete: ["An incomplete Mirsa install exists. Review it under “Old install records” before installing again.", "في تثبيت مرسى ناقص. راجعه تحت «سجلات التثبيت القديمة» قبل ما تثبّت من جديد.", "Eine unvollständige Mirsa-Installation existiert. Prüfe sie unter „Alte Installationseinträge“, bevor du neu installierst.", "Sazkirinek Mirsa ya neqediyayî heye. Berî sazkirina nû, li «Tomarên sazkirinê yên kevn» binere.", "دامەزراندنێکی ناتەواوی مرسی هەیە. پێش دامەزراندنی نوێ لە «تۆمارە کۆنەکانی دامەزراندن» بیپشکنە."],
